<script setup>
import {defaultReplayRun,modeLabel} from './runSelection';
import {subscribeMapStatus} from './mapStatusStream';
import {ref,computed,nextTick,onMounted,onUnmounted} from 'vue';
import DeckMap from './DeckMap.vue';
import PlanningPanel from './PlanningPanel.vue';
import {loadApiReplay} from './apiReplay';
import {prepareMapReplay,mapFrame,assertComparable} from './mapReplay';
import {createScenarioClock} from './mapClock';
import {identity,selectedPackage,latestRequests,requestJSON} from './sceneClient';
import {concentrationColumns,squareCells,dataBounds} from './mapGeometry';
const scenes=ref([]),sceneID=ref('synthetic_multiterrain_100k'),version=ref(1),detail=ref(null),loaded=ref(null),runs=ref([]),replay=ref(null),model=ref(null),compareModel=ref(null),compareID=ref(''),runID=ref(''),status=ref(null),error=ref(''),sourceError=ref(''),busy=ref(false),drawer=ref(''),picked=ref(null),renderer=ref('INITIALIZING'),viewMode=ref('3d'),following=ref(false),clockRange=ref('traffic'),time=ref(0),speed=ref(30),playing=ref(false),threshold=ref(1),mode=ref('no_pump'),map=ref(),layers=ref({terrain:true,water:true,buildings:true,roads:true,planned:true,actual:true,replanned:true,closures:true,facilities:true,vehicles:true,pollution:true,threshold:true,inputVehicles:true,background:true,congestion:true});
const planning=ref(null);
function configured(value){loaded.value={scene:value.scene,scenario:value.scenario,parameters:{[mode.value]:value.parameter},configuration:value.configuration};}
const wsState=ref('OFF');const gate=latestRequests();let clock,raf,disposed=false,closeStatusSocket;
function subscribeStatus(run,tx){closeStatusSocket?.();wsState.value='CONNECTING';closeStatusSocket=subscribeMapStatus(run,{onState:value=>{if(tx.current())wsState.value=value;}});}
const ids=computed(()=>[...new Set(scenes.value.map(s=>s.scenario_id))]);
const versions=computed(()=>scenes.value.filter(s=>s.scenario_id===sceneID.value).sort((a,b)=>b.scenario_version-a.scenario_version));
const chosen=computed(()=>versions.value.find(s=>s.scenario_version===Number(version.value)));
// Release scene versions are identities, not implicit feature flags.
const hasPlanning=computed(()=>Boolean(detail.value?.manifest?.sources?.some(s=>s.source_id==='dispatch-context-v1')));
const label=id=>id==='borden_reference_100k'?'Borden 参考场景':'多地形合成场景';
const endpoint=s=>`/api/v1/scene-catalog/${encodeURIComponent(s.scenario_id)}/versions/${s.scenario_version}`;
const display=computed(()=>replay.value?.sceneDisplay??detail.value?.display);
const frame=computed(()=>model.value?mapFrame(model.value,time.value,{threshold_mg_L:threshold.value}):null);
const comparison=computed(()=>compareModel.value?mapFrame(compareModel.value,time.value,{threshold_mg_L:threshold.value}):null);
const range=computed(()=>model.value?.bounds[clockRange.value==='physical'?'physical_s':'traffic_s']??[0,1]);
const insetCells=computed(()=>squareCells(concentrationColumns(frame.value?.concentration,{local:true})));
const insetBox=computed(()=>{const b=dataBounds(insetCells.value.flatMap(c=>c.points),[0,0,1000,1000]);return [b[0]-50,b[1]-50,b[2]-b[0]+100,b[3]-b[1]+100].join(' ');});
const source=computed(()=>display.value?.coordinate_frame==='synthetic_local_m'?'SYNTHETIC · 地形/建筑仅展示 · 高程×4':'Borden 地理参考 · 局部OSM道路 · 水文未配准');
const pickedOperation=computed(()=>(replay.value?.planning?.context??planning.value?.context)?.facility_access.tasks.find(t=>t.well_id===(picked.value?.well_id??picked.value?.id)));
const points=p=>p.map(x=>x.join(',')).join(' ');
function reset(){planning.value=null;closeStatusSocket?.();closeStatusSocket=null;wsState.value='OFF';clock?.dispose();clock=null;detail.value=null;loaded.value=null;runs.value=[];replay.value=null;model.value=null;compareModel.value=null;compareID.value='';runID.value='';status.value=null;error.value='';sourceError.value='';picked.value=null;playing.value=false;time.value=0;renderer.value='INITIALIZING';}
function makeClock(preserve=time.value){clock?.dispose();const [min,max]=range.value;clock=createScenarioClock({min_s:min,max_s:max,initial_s:Math.max(min,Math.min(max,preserve)),speed:speed.value});const s=clock.snapshot();time.value=s.scenario_time_s;playing.value=false;}
function seek(value){if(!clock)return;const n=Number(value);if(!Number.isFinite(n))return;const s=clock.seek(Math.max(range.value[0],Math.min(range.value[1],n)));time.value=s.scenario_time_s;playing.value=s.playing;picked.value=null;}
function play(){if(!clock)return;const s=playing.value?clock.pause():clock.play(performance.now());playing.value=s.playing;}
function setSpeed(){if(clock)clock.setSpeed(speed.value);}
async function focus(kind){following.value=false;await nextTick();map.value?.fit(kind);}
function setRange(){if(model.value)makeClock();}
function setReplay(data){const m=prepareMapReplay(data);replay.value=data;model.value=m;compareModel.value=null;compareID.value='';runID.value=data.scenario.run_id;status.value=data.status;clockRange.value='traffic';makeClock(Math.max(0,data.samples[0]?.event_time_s??0));picked.value=null;}
async function readRun(r,tx){const expected={scenario_id:sceneID.value,scenario_version:Number(version.value)};identity(r,expected);const value=await loadApiReplay(r.run_id,{signal:tx.signal,expectedScene:expected});if(tx.current()){setReplay(value);subscribeStatus(value.status,tx);}}
async function history(s,tx){const v=await requestJSON(`/api/v1/runs?scenario_id=${encodeURIComponent(s.scenario_id)}&scenario_version=${s.scenario_version}`,{signal:tx.signal});for(const r of v.runs)identity(r,s);if(tx.current())runs.value=v.runs;return v.runs;}
async function choose(changeID=false){if(changeID)version.value=versions.value[0]?.scenario_version??1;const s=chosen.value,tx=gate.begin();reset();busy.value=true;if(!s){busy.value=false;return;}
 await Promise.all([(async()=>{try{const v=selectedPackage(await requestJSON(endpoint(s),{signal:tx.signal}),s);if(tx.current())detail.value=v;}catch(e){if(tx.current())sourceError.value=e.message;}})(),(async()=>{try{const rows=await history(s,tx),latest=defaultReplayRun(rows);if(latest&&tx.current())await readRun(latest,tx);}catch(e){if(tx.current())error.value=e.message;}})()]);if(tx.current())busy.value=false;}
async function selectRun(){closeStatusSocket?.();wsState.value='OFF';const r=runs.value.find(r=>r.run_id===runID.value);if(!r)return;const tx=gate.begin();busy.value=true;error.value='';replay.value=null;model.value=null;clock?.dispose();clock=null;playing.value=false;picked.value=null;try{await readRun(r,tx);}catch(e){if(tx.current())error.value=e.message;}finally{if(tx.current())busy.value=false;}}
async function compare(){compareModel.value=null;if(!compareID.value||!model.value)return;const tx=gate.begin();busy.value=true;try{const value=await loadApiReplay(compareID.value,{signal:tx.signal,expectedScene:{scenario_id:sceneID.value,scenario_version:Number(version.value)}});const other=prepareMapReplay(value);assertComparable(model.value,other);if(tx.current())compareModel.value=other;}catch(e){if(tx.current())error.value=e.message;}finally{if(tx.current())busy.value=false;}}
async function load(){const s=chosen.value,tx=gate.begin();busy.value=true;loaded.value=null;error.value='';try{const v=selectedPackage(await requestJSON(endpoint(s)+'/load',{signal:tx.signal,body:{manifest_sha256:s.manifest_sha256}}),s);if(tx.current())loaded.value=v;}catch(e){if(tx.current())error.value=e.message;}finally{if(tx.current())busy.value=false;}}
async function start(){const config=loaded.value,s=config?.scene,params=config?.parameters[mode.value];if(!s||!params)return;closeStatusSocket?.();wsState.value='OFF';clock?.dispose();clock=null;playing.value=false;model.value=null;replay.value=null;compareModel.value=null;compareID.value='';runID.value='';picked.value=null;const tx=gate.begin(),selectedMode=mode.value;busy.value=true;error.value='';
 try{const health=await requestJSON('/api/v1/health',{signal:tx.signal}),uuid=crypto.randomUUID(),key=crypto.randomUUID();const req={...JSON.parse(JSON.stringify(config.scenario)),run_id:uuid,kind:'run_request',parameter_version:params.id,model_build:health.model_build,payload:{mode:selectedMode,idempotency_key:key}};let run=await requestJSON('/api/v1/runs',{signal:tx.signal,body:req,headers:{'Idempotency-Key':key}});identity(run,s);subscribeStatus(run,tx);
 while(tx.current()){status.value=run;if(['succeeded','failed','cancelled'].includes(run.status))break;await new Promise(r=>setTimeout(r,700));if(!tx.current())return;run=await requestJSON('/api/v1/runs/'+uuid,{signal:tx.signal});identity(run,s);}if(!tx.current())return;await history(s,tx);if(run.status==='succeeded')await readRun(run,tx);else error.value=run.error?.message??run.status;
 }catch(e){if(tx.current())error.value=e.message;}finally{if(tx.current())busy.value=false;}}
function updateThreshold(value){const v=Number(value);if(Number.isFinite(v)&&v>=0)threshold.value=v;}
function loop(now){if(clock&&playing.value){const s=clock.tick(now);time.value=s.scenario_time_s;playing.value=s.playing;}raf=requestAnimationFrame(loop);}
onMounted(async()=>{raf=requestAnimationFrame(loop);const tx=gate.begin();busy.value=true;try{const c=await requestJSON('/api/v1/scene-catalog',{signal:tx.signal});if(c.catalog_version!=='dual-scenes-v1')throw Error('Unknown scene catalog');if(!tx.current())return;scenes.value=c.scenes;if(!ids.value.includes(sceneID.value))sceneID.value=ids.value[0]??'';version.value=versions.value[0]?.scenario_version??1;await choose();}catch(e){if(!disposed)error.value=e.message;}finally{if(!disposed)busy.value=false;}});
onUnmounted(()=>{disposed=true;gate.cancel();cancelAnimationFrame(raf);clock?.dispose();closeStatusSocket?.();});
</script>
<template><div class="map-workspace"><header class="map-toolbar"><a class="map-brand" href="/">B<span>100K</span></a><label class="sr-only" for="map-scene">场景</label><select id="map-scene" aria-label="地图场景" v-model="sceneID" @change="choose(true)"><option v-for="id in ids" :key="id" :value="id">{{label(id)}}</option></select><select aria-label="场景版本" v-model.number="version" @change="choose()"><option v-for="s in versions" :key="s.scenario_version" :value="s.scenario_version">v{{s.scenario_version}}</option></select><select aria-label="地图运行" v-model="runID" @change="selectRun"><option value="">输入预览 / 暂无成功运行</option><option v-for="r in runs.filter(r=>r.status==='succeeded')" :key="r.run_id" :value="r.run_id">{{r.run_id.slice(0,8)}} · {{modeLabel(r)}}</option></select><span class="map-state">{{busy?'加载 / 执行中':status?.status??'输入预览'}} · {{renderer}} · WS {{wsState}}</span><div class="toolbar-spacer"></div><button :class="{active:drawer==='layers'}" @click="drawer=drawer==='layers'?'':'layers'">图层</button><button @click="drawer=drawer==='runs'?'':'runs'">运行</button><button @click="drawer=drawer==='identity'?'':'identity'">来源</button></header>
 <main class="map-stage"><DeckMap v-if="display" :key="sceneID+'@'+version+'@'+(model?.identity.run_id??'preview')" ref="map" :display="display" :model="model" :frame="frame" :identity="model?.identity??chosen" :layers="layers" :view-mode="viewMode" :follow="following" :comparison-model="compareModel" :comparison-frame="comparison" :decision="picked?.kind==='routing-decision'?picked:null" :planning="replay?.planning?.context??planning?.context" @pick="picked=$event" @render-status="renderer=$event.state"/><div v-else class="map-wait">{{error||sourceError||'正在载入场景地图…'}}</div>
 <div class="map-floating-controls"><button @click="focus('activity')">活动区</button><button @click="focus('extent')">100km全域</button><button v-if="display?.terrain" @click="focus('mountain')">山地</button><button @click="focus('pollution')" :disabled="frame?.concentration?.placement!=='synthetic_view_only'">污染域</button><button @click="viewMode=viewMode==='3d'?'2d':'3d'">{{viewMode==='3d'?'切2D':'切3D'}}</button><label><input type="checkbox" v-model="following">跟随首车</label></div>
 <div class="map-context"><span>{{source}}</span><span v-if="sceneID==='borden_reference_100k'">© OpenStreetMap contributors · ODbL · 局部上下文，非100km道路验收</span><span v-if="sourceError">新源包不可用 · 已发布历史仍可重放</span><span v-if="error" role="alert">{{error}}</span></div>
 <aside v-if="drawer" class="map-drawer"><button class="drawer-close" @click="drawer=''">关闭 ×</button><template v-if="drawer==='layers'"><h2>地图图层</h2><label v-for="(name,key) in {terrain:'地形（高程×4仅展示）',water:'河流',buildings:'合成城市建筑',roads:'实际网络lane几何',planned:'计划路线 · 蓝',actual:'实际已行 · 黄',replanned:'真实重规划 · 紫',closures:'封路事件 · 红',facilities:'基地 / 井场',vehicles:'真实采样车辆',pollution:'地下水浓度XY列最大值',threshold:'阈值区域',background:'社会车辆 · 真实SUMO / synthetic需求',congestion:'道路实测状态 · 未观测灰色'}" :key="key"><input type="checkbox" :disabled="(key==='planned'&&frame?.capabilities.planned_routes.status==='NOT_RUN')||(key==='replanned'&&frame?.capabilities.replanned_routes.status==='NOT_RUN')" :checked="layers[key]" @change="layers={...layers,[key]:$event.target.checked}">{{name}}</label><label v-for="(cap,name) in frame?.capabilities??{}" :key="name"><input v-if="['dynamic_speed_limits','live_vehicle_stream'].includes(name)" type="checkbox" disabled> {{name}}：{{cap.status}} · {{cap.reason}}</label><label>可视比较阈值 mg/L <input aria-label="浓度可视阈值" type="number" min="0" :value="threshold" @change="updateThreshold($event.target.value)"></label><p>阈值仅比较展示，不是健康或监管标准。地形与建筑不改变交通/水文动力。</p></template>
 <template v-else-if="drawer==='runs'"><h2>运行与比较</h2><p v-for="(g,m) in chosen?.availability??{}" :key="m">{{m}}：{{g.allowed?'允许显式运行':g.blockers.join(' · ')}}</p><button v-if="!hasPlanning" :disabled="busy||!detail" @click="load">加载场景配置</button><select aria-label="地图运行工况" v-model="mode"><option v-for="(g,m) in chosen?.availability??{}" :key="m" :value="m" :disabled="!g.allowed">{{m}}</option></select><PlanningPanel v-if="hasPlanning&&chosen" :key="sceneID+'@'+version" :scene="chosen" v-model:mode="mode" :replay="replay" :frame="frame" @metadata="planning=$event" @configured="configured" @invalidated="loaded=null"/><button :disabled="busy||!loaded?.parameters[mode]" @click="start">启动运行</button><p v-if="!hasPlanning">显式物理评价窗0–21900日；参考日14600；控制窗signed限制保持。</p><h3>同版本 / 同网络比较</h3><select aria-label="对比运行" v-model="compareID" @change="compare"><option value="">关闭对比</option><option v-for="r in runs.filter(r=>r.status==='succeeded'&&r.run_id!==runID)" :key="r.run_id" :value="r.run_id">{{r.run_id}}</option></select><p v-if="compareModel">灰色为另一运行已行路径，不称同run重规划。UUID {{compareID}}</p><p v-if="frame?.backgroundSummary" aria-label="背景交通本次运行最终统计">本次运行最终统计（不是当前播放时刻）：背景请求 {{frame.backgroundSummary.requested}} · 实际出发 {{frame.backgroundSummary.actually_departed}} · 到达 {{frame.backgroundSummary.arrived}} · 不可达 {{frame.backgroundSummary.unreachable}} · 有真实样点车辆 {{frame.backgroundSummary.with_samples}}。</p><h3>同run路径与ETA更新（估计）</h3><p>ETA为剩余边旅行时间估计（含当前整边），不是实际到达时刻。</p><button class="eta-decision-btn" :title="d.reason+' · ETA '+d.old_eta_s+' → '+d.new_eta_s" v-for="d in frame?.routingDecisions??[]" :key="d.id" @click="seek(d.decision_s);picked=d">{{d.vehicle_id}} · {{d.decision_s}}s · {{d.reason}} · 预计ETA {{d.old_eta_s.toFixed(1)}}→{{d.new_eta_s.toFixed(1)}}s</button><h3>历史运行</h3><p v-for="r in runs" :key="r.run_id">{{r.run_id}} · {{r.status}}</p></template>
 <template v-else><h2>来源与身份</h2><p>道路不按装饰修改，全部来自核SHA的net lane几何。河桥/合成建筑/地形仅展示。</p><p v-if="sourceError">{{sourceError}}</p><pre>{{JSON.stringify(model?.identity??chosen,null,2)}}</pre><p v-for="s in replay?.sceneManifest?.sources??detail?.manifest?.sources??[]" :key="s.source_id">{{s.source_id}} · {{s.license}}<br>{{s.reference}}</p><a href="/?classic=1">经典审查工作台</a><a v-if="runID" :href="'/?run_id='+runID">旧独立运行回放</a><a v-if="runID" :href="'/api/v1/runs/'+runID+'/exports/earth.kmz?profile=earth_web'">下载KMZ（沿用配准门禁）</a><p>可选Google SDK保留在经典独立回放；不是默认地图依赖。</p></template></aside>
 <aside v-if="picked" class="map-object-card" aria-label="地图对象详情"><button @click="picked=null">关闭 ×</button><h3>{{picked.kind??'对象'}} · {{picked.id??picked.vehicle_id??picked.edge_id}}</h3><p v-if="picked.position_m">服务坐标 {{picked.position_m.map(x=>Number(x).toFixed(2)).join(', ')}} m</p><p v-if="picked.concentration_mg_L!==undefined">C={{picked.concentration_mg_L}} mg/L · cell {{picked.cell_id}} · XY列最大值（{{picked.column_cell_count}}层）</p><p v-if="pickedOperation">SYNTHETIC操作点 → 原模型cell {{pickedOperation.cell_id}} · local xyz {{pickedOperation.model_local_xyz_m?.join(', ')}}；独立操作关联，不是现场井配准。</p><p v-if="picked.local_xyz_m">原模型xyz {{picked.local_xyz_m.join(', ')}} m</p><p>{{picked.task_state??picked.phase??picked.source??''}}</p><p v-for="task in picked.tasks??[]" :key="task.task_id">任务 {{task.task_id}} · 车辆 {{task.vehicle_id}} · {{task.state}}</p><p v-for="event in picked.events??[]" :key="event.event_id">{{event.kind}} · {{event.event_time_s}} s</p><p>scenario_time_s={{time.toFixed(2)}} · day {{frame?.model_day.toFixed(8)}}</p><details><summary>对象记录</summary><pre>{{JSON.stringify(picked,null,2)}}</pre></details></aside>
 <aside v-if="frame?.concentration?.placement==='local_only'&&layers.pollution" class="map-hydro-inset" aria-label="同步局部地下水"><h3>独立局部地下水 · 未地理配准</h3><svg :viewBox="insetBox" role="img" aria-label="同步浓度局部图"><polygon v-for="c in insetCells" :key="c.cell_id" :points="points(c.points)" :fill="'rgba(255,150,55,'+(0.15+Math.min(1,Math.max(0,c.concentration_mg_L/500))*.8)+')'" @click="picked=c"/></svg><p>XY列最大值 · mg/L · 原采样日 {{frame.concentration.sampled_model_day}}<br>与主图同一时钟，不叠到真实地理坐标</p></aside>
 <div class="map-legend"><span class="legend-blue">━ 计划</span><span class="legend-yellow">━ 已行</span><span class="legend-purple">━ 重规划</span><span class="legend-red">━ 封路</span><span v-if="comparison">━ 对比run已行（灰）</span><span v-if="frame?.edgeStates?.length">拥堵红 / 通畅青 / 未观测灰 · 仅采样边 · 背景车蓝</span><span>浓度 mg/L · XY列max · 对数色标0–500</span><span v-if="frame?.concentration">实际帧 #{{frame.concentration.frame_index}} / day {{frame.concentration.sampled_model_day}}</span></div>
 </main>
 <footer class="map-timeline" aria-label="统一场景时间轴"><div class="timeline-row"><button @click="seek(0)" :disabled="!clock">归零</button><button class="primary" @click="play" :disabled="!model">{{playing?'暂停':'播放'}}</button><input aria-label="统一场景秒" type="range" :min="range[0]" :max="range[1]" step="0.1" :value="time" @input="seek($event.target.value)" :disabled="!model"><input aria-label="精确场景秒" class="time-number" type="number" :min="range[0]" :max="range[1]" :value="time.toFixed(2)" @change="seek($event.target.value)" :disabled="!model"><select aria-label="统一倍速" v-model.number="speed" @change="setSpeed"><option :value="1">1×</option><option :value="30">30×</option><option :value="300">300×</option><option :value="86400">1日/s</option></select><select aria-label="时间窗口" v-model="clockRange" @change="setRange"><option value="traffic">应急窗口</option><option value="physical">完整物理时域</option></select></div><div class="timeline-meta"><span>{{time<0?'参考日前历史 · ':''}}t={{time.toFixed(2)}} s · model_day={{frame?.model_day.toFixed(8)??'—'}}</span><select aria-label="跳至应急事件" @change="seek($event.target.value)"><option value="">事件定位</option><option v-for="e in frame?.taskEvents??[]" :key="e.event_id" :value="e.event_time_s">{{e.event_time_s}}s · {{e.well_id}} · {{e.kind}}</option><template v-for="c in frame?.closures??[]" :key="c.edge_id"><option :value="c.start_s">{{c.start_s}}s · {{c.edge_id}}封闭</option><option :value="c.stop_s">{{c.stop_s}}s · {{c.edge_id}}重开</option></template></select><select aria-label="跳至真实水文帧" @change="clockRange='physical';setRange();seek($event.target.value)"><option value="">实际NPZ帧</option><option v-for="(day,i) in replay?.concentration?.times_day??[]" :key="i"  :value="(day-(replay?.scenario.payload.time_axis.reference_model_day??0))*86400">#{{i}} day {{day}}{{day<(replay?.scenario.payload.time_axis.reference_model_day??0)?' · 参考日前历史':''}}</option></select><span>同一时钟驱动车辆 / 封路 / 启停 / 实际浓度帧</span></div></footer>
 </div></template>
